<?php
namespace App\Services;
use App\Models\Producto;
class ValidacionBiologicaService { public function incompatibles(Producto $fish, iterable $cart): array { $out=[];$aggressive=['agresivo','territorial']; foreach($cart as $other){if(!$other instanceof Producto||!$other->es_ser_vivo||$other->id===$fish->id)continue;$ph=$fish->ph_min!==null&&$fish->ph_max!==null&&$other->ph_min!==null&&$other->ph_max!==null&&max((float)$fish->ph_min,(float)$other->ph_min)>min((float)$fish->ph_max,(float)$other->ph_max);$temp=$fish->temp_min!==null&&$fish->temp_max!==null&&$other->temp_min!==null&&$other->temp_max!==null&&max((float)$fish->temp_min,(float)$other->temp_min)>min((float)$fish->temp_max,(float)$other->temp_max);$a=mb_strtolower($fish->temperamento??'');$b=mb_strtolower($other->temperamento??'');$temperament=(in_array($a,$aggressive,true)&&in_array($b,['pacifico','comunitario'],true))||(in_array($b,$aggressive,true)&&in_array($a,['pacifico','comunitario'],true));if($ph||$temp||$temperament)$out[]=['producto'=>$other->nombre,'causa'=>$ph?'Rangos de pH incompatibles':($temp?'Rangos de temperatura incompatibles':'Temperamentos incompatibles')];}return $out;} }
